    "دع الكتلبل يتدلى أمام جسمك مع مد ذراعيك بالكامل.",
    "في حركة واحدة متصلة، افرد وركيك بقوة وهز كتفيك واسحب الكتلبل لأعلى باتجاه كتفيك.",
