    "حافظ على رفع صدرك وإرجاع كتفيك للخلف طوال التمرين.",
    "اسحب أحد المقبضين نحو جذعك مع إبقاء المقبض الآخر ثابتاً.",
    "اعصر لوحي كتفيك معاً في نهاية الحركة.",
    "أعد المقبض ببطء إلى وضع البداية وكرر الحركة على الجانب الآخر.",
    "استمر في التبديل بين الجانبين للعدد المطلوب من التكرارات."
