    "تعلق مع مد ذراعيك بالكامل والحفاظ على استقامة جسمك.",
    "قم بتفعيل عضلات ظهرك واسحب جسمك للأعلى نحو المقابض موجهاً صدرك للأمام.",
    "استمر في السحب حتى يتجاوز ذقنك مستوى المقابض.",
