    "مع الشهيق، أنزل الدمبل ببطء إلى الجانب حتى تشعر بتمدد في عضلات صدرك.",
    "ازفر واستخدم عضلات صدرك لرفع الدمبل للأعلى عائداً لوضع البداية.",
