    "قف في مواجهة البار مع مباعدة قدميك بعرض الوركين وتوجيه أصابع قدميك للأمام.",
    "ضع مشطي قدميك على حافة درجة أو منصة، مع ترك كعبيك معلقين للخارج.",
    "أمسك بالبار للحصول على الدعم.",
    "ارفع كعبيك لأعلى مستوى ممكن، رافعاً جسمك لأعلى على أصابع قدميك.",
    "توقف للحظة في الأعلى، ثم أنزل كعبيك ببطء إلى وضع البداية.",
