    "مع تثبيت الجزء العلوي من ذراعك، ازفر واثنِ ذراعك لرفع الوزن لأعلى مع قبض عضلة البايسبس.",
    "استمر في رفع الدمبل حتى تنقبض عضلة البايسبس بالكامل ويصبح الدمبل عند مستوى الكتف.",
    "اثبت على هذا الوضع للحظة مع عصر عضلة البايسبس.",
