    "ثبّت دعامة الذراعين (الآرم بلاستر) بشكل محكم ومريح على صدرك وذراعيك.",
    "مع تثبيت ذراعيك العلويين على الدعامة، ازفر واثنِ دمبلاً واحداً نحو كتفك مع قبض عضلة البايسبس.",
